Method.Implementation:
    $$$TRACE( "**** Process X12 files in: " _ pSourceDir)
    set numFile = 0
	if ( ##class(%File).DirectoryExists(pSourceDir))
	{

		Set tSC = ##class(%File).FileSetExecute(.tHandle, pSourceDir, pWildCard)

		If $$$ISOK(tSC) {

			Set tAtEnd = 0
			For {
				Set tSC = ##class(%File).FileSetFetch(.tHandle, .tRow, .tAtEnd)
				If '$$$ISOK(tSC)!($ListLength(tRow)<6) Quit

				set messages = ##class(%File).%New($List(tRow, 1))

				set attr = ##class(%File).Attributes($List(tRow, 1))
				// $$$TRACE( $List(tRow, 1) _": " _ $BIT($FACTOR(attr),15) _": " _ $BIT($FACTOR(attr),16)
				// FOR i=1:1:16 {WRITE $BIT($FACTOR(attr),i) }
				// the returned value represents the mode map
				// 16384: 0x4000 - directory
				// 32768: 0x8000 - regular file
				if ( $BIT($FACTOR(attr),16) = 1) // Regular file
				{

					$$$TRACE( "**** Process X12 file: " _ $List(tRow, 1) _", " _ $List(tRow, 3)) 
					// WRITE !, "**** Process X12 file: " _ $List(tRow, 1) _", " _ $List(tRow, 3)

					Do ..ProcessFile($List(tRow, 1))

					set numFile = numFile + 1

					If tAtEnd Quit
				}
			}	
			Set tSC = ##class(%File).FileSetClose(.tHandle)
		}

	}
	$$$TRACE( "Processed " _ numFile _ " files in: " _ pSourceDir)
	return numFile

	if (receiptDtTm = "")
	{
		set receiptDtTm = $ZDATETIME(##class(%File).GetFileDateCreated(fileName),3, 1)
	}

	set source = ##class(EnsLib.EDI.X12.Document).ImportFromFile(fileName,, .x12Stat)

 	if ( (x12Stat = 1) && ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
	 {
		 Do ..ProcessX12Doc(source, fileName, stat, receiptDtTm )
	 }
	 else
	 {
		 $$$TRACE( "ImportFromFile failed " _stat _ ", filesize: " _ ##class(%File).GetFileSize(fileName))
	 }

	$$$TRACE( "Processed " _ fileName)

	set sessionId = obj.SessionID
	set flNm = obj.streamContainer.OriginalFilename
	set stat = obj.status
	set direc = obj.direction
	set mId = obj.%Id()
	set receiptDtTm = ""

	&SQL(select ID into :hId from Ens.MessageHeader where MessageBodyClassName = 'IHC.ITF.ITFCOMMON.DStruc.StoreX12' and MessageBodyId = :mId)
	$$$TRACE("ProcessDStrucStoreX12 MessageBodyId = " _mId _", MessageHeader: " _hId _", LinkId: " _ obj.LinkId)
	#dim hm As Ens.MessageHeader = ##class(Ens.MessageHeader).%OpenId(hId)
	if ($IsObject(hm))
	{
	        set receiptDtTm = ##class(%Library.UTC).ConvertUTCtoLocal(hm.TimeCreated)
	}
	else
	{
		&SQL(select ID into :hId from Ens.MessageHeader where SessionID = :sessionId)
		set hm = ##class(Ens.MessageHeader).%OpenId(hId)
		if ($IsObject(hm))
		{
	        set receiptDtTm = ##class(%Library.UTC).ConvertUTCtoLocal(hm.TimeCreated)
		}
	}
	if (receiptDtTm = "")
	{
		set receiptDtTm = $ZDATETIME($HOROLOG,3, 1)
	}

	set source = ##class(EnsLib.EDI.X12.Document).ImportFromLibraryStream(obj.streamContainer.Stream, .tSC)

 	if ( ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
	{
		 return ..ProcessX12Doc(source, flNm, stat, receiptDtTm, direc, sessionId, obj.destinationFileName, obj.interchangeSenderID, obj.interchangeReceiverID, obj.LinkId )
	}
	else
	{
		$$$LOGERROR("ImportFromLibraryStream failed " _ tSC _", EnsLib.EDI.X12.Document: " _ source )
		return "0"
	}


	#dim source As EnsLib.EDI.X12.Document
	set receiptDtTm = ""
	$$$TRACE("ProcessStreamContainer " _ streamContainer.OriginalFilename _" - Stream size: " _ streamContainer.Stream.Size)
	Do streamContainer.Stream.Rewind()
	if (receiptDtTm = "")
	{
		set mId = streamContainer.%Id()
	  	&SQL(select ID into :hId from Ens.MessageHeader where MessageBodyClassName = 'Ens.StreamContainer' and MessageBodyId = :mId)
	  	$$$TRACE("MessageBodyId = " _mId _", MessageHeader: " _hId)
	  	#dim hm As Ens.MessageHeader = ##class(Ens.MessageHeader).%OpenId(hId)
	  	if ($IsObject(hm))
	  	{
	  	       set receiptDtTm = ##class(%Library.UTC).ConvertUTCtoLocal(hm.TimeCreated)
	  	}
	  	if (receiptDtTm = "")
	    {
		   set receiptDtTm = $ZDATETIME($HOROLOG,3, 1)
	    }
	  	set sessionId = hm.SessionId
	  	$$$TRACE("Session: " _ sessionId _ ", TimeCreated UTCtoLocal: " _ hm.TimeCreated)
	}

	set source = ##class(EnsLib.EDI.X12.Document).ImportFromLibraryStream(streamContainer.Stream, .tSC)

 	if ( ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
	{
		 return ..ProcessX12Doc(source, streamContainer.OriginalFilename, stat, receiptDtTm, direction, sessionId )
	}
	else
	{
		$$$LOGERROR("ImportFromLibraryStream failed " _ tSC _", EnsLib.EDI.X12.Document: " _ source )
		return "0"
	}


	#dim source As EnsLib.EDI.X12.Document
	if ( fileStream.Size < 100)
	{
		return "Stream size is not valie"
	}

	 set source = ##class(EnsLib.EDI.X12.Document).ImportFromLibraryStream(fileStream, .tSC)

 	if ( ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
	 {
		 return ..ProcessX12Doc(source, fileName, stat, receiptDtTm, direction )
	 }
	 else
	 {
		 $$$TRACE( "ImportFromLibraryStream failed " _tSC _ ", filesize: " _ fileStream.Size)
	 }

#dim source As EnsLib.EDI.X12.Document
if ($L(x12Data) > 100)
{

 	set source = ##class(EnsLib.EDI.X12.Document).ImportFromString(x12Data)
 	if ( ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
 	{
	 	return ..ProcessX12Doc(source, fileName, stat, receiptDtTm, direction, sessionId)
 	}
}

return ""

$$$TRACE("UpdateTable: IHC.X12.Data" _ tblNm _ ", update status: " _stat _", SessionId: "_ sessionId)

			set sqlStr = "UPDATE IHC_X12.Data" _ tblNm _ "  set status = '" _ stat  _"'"

			if (destFile '= "")
			{
				set sqlStr = sqlStr _ ", DestinationFileName = '" _ destFile _"'"
			}

			if (isaSender '= "")
			{
				set sqlStr = sqlStr _ ", InterchangeSenderID = '" _ isaSender _"'"
				set senderName = ..GetTpName(isaSender)
				if (senderName '= "")
				{
					set sqlStr = sqlStr _ ", InterchangeSenderName = '" _ senderName _"'"
				}
			}
			if ( isaReceiver '= "")
			{
				set sqlStr = sqlStr _ ", InterchangeReceiverID = '" _ isaReceiver _"'"
				set receiverName = ..GetTpName(isaSender)
				if (receiverName '= "")
				{
					set sqlStr = sqlStr _ ", InterchangeReceiverName = '" _ receiverName _"'"
				}
			}
			if ( LinkId '= "")
			{
				set sqlStr = sqlStr _ ", LinkId = '" _ LinkId _"'"
			}

			set sqlStr = sqlStr _ " where SessionId = " _ sessionId 

			Set rs = ##class(%SQL.Statement).%ExecDirect(,sqlStr )
			$$$TRACE(sqlStr _ ": " _ rs.%SQLCODE)

	set x12Doc.DocType = "HIPAA_5010:Interchange:Group"
		  Set tSC =x12Doc.BuildMap()
		  if ($$$ISERR( tSC ))
		  {
			  $$$TRACE("Invalid DocType")
			  QUIT "Invalid DocType, BuildMap failed"
		  }
		  // $$$TRACE( "X12 Child count:" _ x12Doc.ChildCount)
		  if (x12Doc.ChildCount = 0)
		  {
			  //TA1
			  return ..ProcessTA1(x12Doc, "TA1", fileName, stat, receiptDtTm, direction, sessionId)
		  }

		  #dim individualGroup As EnsLib.EDI.X12.Document 
		  set individualGroup = x12Doc.getNthChild(1,2)

		  #dim STRecord As EnsLib.EDI.X12.Document 

		  set STRecord=individualGroup.getNthChild(1,2)

		  set transType = ..GetTransType(STRecord)	
		  if (transType = "")
		  {
			  $$$LOGERROR("Unknown transaction type, ST segment: " _ STRecord)
			  return "Unknown transaction"
		  } 

		  $$$TRACE( "ProcessX12Doc: " _ transType _", File: " _ fileName _ ", Session: " _ sessionId _ ", Stat: " _ stat)
		  set tblNm = $SELECT(transType [ "837" : "837",1: transType) // strip P,I,D

		  if (receiptDtTm = "")
		  {
		  	set receiptDtTm = $ZDATETIME($HOROLOG,3, 1)
		  }
		  set cnt = 0

		  if (sessionId '= "")
			{
				set sqlStr = "Select count(*) As CNT FROM IHC_X12.Data" _ tblNm _ " where SessionId = " _ sessionId 
				Set rs = ##class(%SQL.Statement).%ExecDirect(,sqlStr )
				$$$TRACE(sqlStr _ ": ExecDirect stat: " _ rs.%SQLCODE)

				While rs.%Next() {
					set cnt = rs.%Get("CNT")
					$$$TRACE(sqlStr _ "- count(*): " _ cnt) 

 				}
			}

			if (cnt > 0)
			{
				Do ..UpdateTable(tblNm, sessionId, stat, destFile, isaSender , isaReceiver, LinkId)				

				RETURN "UpdateTable complete "
			}
			set parentId = ""

		  if (transType = "835")
		  {	   	  
		  		set parentId = ..Process835(x12Doc, transType, fileName, stat, receiptDtTm, direction, sessionId)
		  }
		  elseif (transType [ "837")
		  {	   	  
		  		set parentId = ..Process837(x12Doc, transType, fileName, stat, receiptDtTm, direction, sessionId)
		  }
		  elseif (transType = "270")
		  {	   	  
		  		set parentId = ..Process270(x12Doc, transType, fileName, stat, receiptDtTm, direction, sessionId)
		  }
		  elseif (transType = "271")
		  {	   	  
		  		set parentId = ..Process271(x12Doc, transType, fileName, stat, receiptDtTm, direction, sessionId)
		  }
		  elseif (transType = "276")
		  {	   	  
		  		set parentId = ..Process276(x12Doc, transType, fileName, stat, receiptDtTm, direction, sessionId)
		  }
		  elseif (transType = "277")
		  {	   	  
		  		set parentId = ..Process277(x12Doc, transType, fileName, stat, receiptDtTm, direction, sessionId)
		  }
		  elseif (transType = "277CA")
		  {	   	  
		  		set parentId = ..Process277CA(x12Doc, transType, fileName, stat, receiptDtTm, direction, sessionId)
		  }
		  elseif (transType = "999")
		  {	   	  
		  		set parentId = ..Process999(x12Doc, transType, fileName, stat, receiptDtTm, direction, sessionId)
		  }
		  else
		  {
			  $$$LOGERROR("Unknown transaction type: " _ transType)
			  return "Invalid transaction"
		  }
		  Do ..UpdateTable(tblNm, sessionId, stat, destFile, isaSender , isaReceiver, LinkId)

		  if ($IsObject(x12Doc))
		  {
		    Do x12Doc.%Save()
		  	set x12DocId = x12Doc.%Id() 
		  	set delStat = x12Doc.%DeleteId(x12Doc.%Id())
		  	$$$TRACE("ProcessX12Doc Delete: " _ delStat _ ", Id: " _ x12DocId)
		  }
		  return stat

	 set parentId = "", objCnt =0
	 set buildStat = $$$OK
	 set elObj = ##class(IHC.X12.Data835).%New()
	 Do ..InitFirstObject(elObj, x12Doc, fileName, stat, receiptDtTm, direction, sessionId ) 
	 if ($GET(^ItfGlobalX12IdKey("X12Data" _ transType)) = "")
	 {
	 	set ^ItfGlobalX12IdKey("X12Data" _ transType) = 1
	 }
	 else
	 {
		 Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
		 set elObj.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
	 }
	 $$$TRACE( "Process835 ID: " _ ^ItfGlobalX12IdKey("X12Data" _ transType))
	 // WRITE !, "Process835 ID: " _ ^ItfGlobalX12IdKey("X12Data" _ transType)
	set parentId = "", objCnt =0
	set GSCounter = x12Doc.ChildCount

	for gsInt=1:1:GSCounter
    { 
        #dim individualGroup As EnsLib.EDI.X12.Document
        set individualGroup = x12Doc.getNthChild(gsInt,2)

		$$$TRACE(  "# of STs: " _ individualGroup.ChildCount)
		  set elClmObj = $$$NULLOREF
		  FOR stInd=1:1:individualGroup.ChildCount

		  {

			  #dim STRecord As EnsLib.EDI.X12.Document 

			  set STRecord=individualGroup.getNthChild(stInd,2)

			  set STRecord.DocType = "HIPAA_5010:" _ transType

			  set buildStat = STRecord.BuildMap()

			  if ($$$ISERR(buildStat))
			  {
				  $$$LOGERROR("ST build: " _  transType_ ": " _  buildStat)
				  set elObj.Status = "Data"
				  Do elObj.%Save()

				  set parentId = elObj.%Id()
				  $$$TRACE(  "  IHC.X12.Data835 Saved, ID: " _ elObj.%Id())
				  WRITE !, "  buildStat: IHC.X12.Data835 Saved, ID: " _ elObj.%Id()

			  }


			  $$$TRACE(  "ST build: " _  transType_ ": " _  stat _ ", Seg Count: " _ STRecord.SegCountGet() _ ", Separators: " _ STRecord.Separators )
			  set segX12Data = ""


	  		  set newClp = 0, newLX = 0
			  FOR ind=1:1:STRecord.SegCountGet()
			  {

				set segPath = STRecord.GetSegmentPath(ind, .stat)	  	
			  	set segVal = STRecord.GetValueAt(segPath,, .stat)


			  	if ($FIND(segVal,"CLP") = 4)
			  	{
				  	// WRITE !,  " -- CLP -- " _ segVal _", newClp:" _ newClp _", " _ elClmObj.ClaimSubmitterId
				  	if (newClp = 1)
				  	{
					  	if ($IsObject(elClmObj))
					  	{
						  	Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
						  	set elClmObj.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
						  	set elClmObj.X12DataParentId = parentId
						  	set elClmObj.x12Data = segX12Data
						  	set elClmObj.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)

					  		Do elClmObj.%Save()
					  		Do $INCREMENT(objCnt)
					  		// WRITE !, "CLP IHC.X12.Data835 Save, ID: " _ elClmObj.%Id()
					  		$$$TRACE(  "CLP IHC.X12.Data835 Save, ID: " _ elClmObj.%Id())

					  		set elClmObj = elObj.%ConstructClone()

					  		Do elClmObj.x12DataStream.Clear()			  		
					  	}
				  	}

				  	set elClmObj.ClaimSubmitterId = $PIECE(segVal, x12Doc.ElementSeparator , 2)
				  	set elClmObj.ClaimPaymentAmount = $PIECE(segVal, x12Doc.ElementSeparator , 5)
			  		set elClmObj.TotalClaimCharge = $PIECE(segVal, x12Doc.ElementSeparator , 4)

					set segX12Data = segVal _ STRecord.SegmentTerminator // Start new X12 segment

					set elClmObj.SeqNum = objCnt
					set newClp = 1

			  	}
			  	elseif ($FIND(segVal,"BPR") = 4)
			  	{

				  	set elObj.PaymentMethod = $PIECE(segVal, x12Doc.ElementSeparator , 5) 
				  	set elObj.PaymentAmount = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  	set elObj.CheckIssueDate = $PIECE(segVal, x12Doc.ElementSeparator , 17)
				  	if ($IsObject(elClmObj))
				  	{
					  	set elClmObj.CheckIssueDate = $PIECE(segVal, x12Doc.ElementSeparator , 17)
				  	}

			  	}
			  	elseif ($FIND(segVal,"DTM") = 4)
			  	{
				  	set seg1Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
				  	Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.DTPLookup", seg1Val, .retVal)

				  	if (seg1Val = "472") 
				  	{
				  		set elClmObj.ServiceDate = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  	}

			  	}


			  	elseif (($FIND(segVal,"REF") = 4))
			  	{
				  	if ($PIECE(segVal, x12Doc.ElementSeparator , 2) = "TJ")
				  	{
					  	set elObj.PayeeTaxID = $PIECE(segVal, x12Doc.ElementSeparator , 3) 

				  	}
			  	}
			  	elseif ( ($FIND(segVal,"NM1") = 4) || ($FIND(segVal,"N1") = 3) )
			  	{

				  	set seg1Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
				  	Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.NM1lookup", seg1Val, .retVal)

				  	if (seg1Val = "PE")
				  	{
					  	set elObj.Payee = $PIECE(segVal, x12Doc.ElementSeparator , 3)
					  	set elObj.PayeeID = $PIECE(segVal, x12Doc.ElementSeparator , 5)
				  	}
				  	if (seg1Val = "PR")
				  	{
					  	set elObj.Payer = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  	}


				  	if (seg1Val = "IL")
				  	{
					  	set elClmObj.Insured = $PIECE(segVal, x12Doc.ElementSeparator , 5) _ " " _ $PIECE(segVal, x12Doc.ElementSeparator , 4)
					  	set elClmObj.InsuredId = $PIECE(segVal, x12Doc.ElementSeparator , 10)

				  	}

				  	if (seg1Val = "QC")
				  	{
					  	set elClmObj.PatientName = $PIECE(segVal, x12Doc.ElementSeparator , 5) _ " " _ $PIECE(segVal, x12Doc.ElementSeparator , 4)
					  	//set elClmObj.DependentId = $PIECE(segVal, x12Doc.ElementSeparator , 10)
				  	}
				  	if ( (seg1Val = "82") || (seg1Val = "71")) // Provider Name' and 'Provider NPI'
				  	{

					  	set elClmObj.Provider = $PIECE(segVal, x12Doc.ElementSeparator , 5) _ " " _ $PIECE(segVal, x12Doc.ElementSeparator , 4)
					  	set elClmObj.ProviderNpi = $PIECE(segVal, x12Doc.ElementSeparator , 10)
				  	}

			  	}
			  	elseif ($FIND(segVal,"TRN") = 4)
			  	{

				 	set elObj.TrnId = $PIECE(segVal, x12Doc.ElementSeparator , 3)


			  	}


			  	elseif ($FIND(segVal,"ST") = 3)
			  	{
				  	set elObj.TransactionSetControlNumber = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  	// WRITE !,  "-- ST -- "
				  	set newLX = 0, newClp = 0
			  	}
			  	elseif ($FIND(segVal,"SE") = 3) 
			  	{
				   	set newLX = 0, newClp = 0
					Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
					if ($IsObject(elClmObj))
					{
						set elClmObj.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
						set elClmObj.X12DataParentId = parentId
						set elClmObj.x12Data = segX12Data
						set elClmObj.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)  	
					  	set stat = elClmObj.%Save()
					  	Do $INCREMENT(objCnt)
					  	$$$TRACE(  "-- SE Save -- " _ stat _", Id: " _ elClmObj.%Id()_", Parent Id: " _ parentId)
					  	// WRITE !, "-- SE Save -- " _ stat _", Id: " _ elClmObj.%Id()_", Parent Id: " _ parentId
				  	}
				  	else
				  	{
					  	 Do elObj.%Save()
				  		 Do $INCREMENT(objCnt)
						 set parentId = elObj.%Id()
						 $$$TRACE(  " Parent IHC.X12.Data835 Saved, ID: " _ elObj.%Id())
						 // WRITE !, " Parent IHC.X12.Data835 Saved, ID: " _ elObj.%Id()					   				  

				  	}

			  	}

			  	elseif ($FIND(segVal,"LX") = 3)
			  	{
				  	// WRITE !,  " -- LX -- " _ segVal _", newLX: " _ newLX _ ", newClp: " _ newClp
	  			  	set seg3Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)

	  			  	if (parentId = "")
				  	{
				  		  Do elObj.%Save()
				  		  Do $INCREMENT(objCnt)
						  set parentId = elObj.%Id()
						  $$$TRACE(  " Parent IHC.X12.Data835 Saved, ID: " _ elObj.%Id())
						  // WRITE !, " Parent IHC.X12.Data835 Saved, ID: " _ elObj.%Id()					   				  


						  set elClmObj = $$$NULLOREF

						  set elClmObj = elObj.%ConstructClone()
						  Do elClmObj.x12DataStream.Clear()
						  set elClmObj.SeqNum = $PIECE(segVal, x12Doc.ElementSeparator , 2)
			  		}

				  	elseif ( (newLX = 1) && ($IsObject(elClmObj)) )
				  	{

						  	Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
						  	set elClmObj.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
						  	set elClmObj.X12DataParentId = parentId
						  	set elClmObj.x12Data = segX12Data
						  	set elClmObj.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)
					  		Do elClmObj.%Save()
					  		Do $INCREMENT(objCnt)
					  		$$$TRACE(  " -- LX IHC.X12.Data835 Saved, ID: " _ elClmObj.%Id())

					  	set elClmObj = elObj.%ConstructClone()
					  	Do elClmObj.x12DataStream.Clear()
					  	set newClp = 0
					  	set elClmObj.SeqNum = $PIECE(segVal, x12Doc.ElementSeparator , 2)

				  	}

			  		else
			  		{
				  		set elClmObj = $$$NULLOREF
				  		set elClmObj = elObj.%ConstructClone()	
				  		Do elClmObj.x12DataStream.Clear()				  	
					  	set elClmObj.SeqNum = $PIECE(segVal, x12Doc.ElementSeparator , 2)
			  		}
			  		set newClp = 0, newLX = 1
			  	}

			  	else
			  	{
				  	$$$TRACE( ind _". " _ STRecord.DocType _ ": Segment not parsed: " _ segPath _ ": " _ segVal _", stat: " _ stat)
			  	}
			  	if ($FIND(segVal,"CLP") '= 4)
			  	{
			  		set segX12Data = segX12Data _ segVal _ STRecord.SegmentTerminator // Append data
			  	}
			  }
		  }
		  set elObj.SeqNum = objCnt - 1
		  Do elObj.%Save()
    }
     if ( (objCnt = 0) && ($$$ISERR(buildStat)) )
     {
     	// Add an entry to WorkFlow
		Do ..InsertWF(elObj, transType)
     }

	$$$TRACE(  " --- Processing complete: IHC.X12.Data835, ClaimPayment, # rows:" _ objCnt)
	// WRITE !, " --- Processing complete: IHC.X12.Data835, ClaimPayment, # rows:" _ objCnt
	return elObj.%Id()

	set elObj = ##class(IHC.X12.Data837).%New()
	#dim elObjSub As IHC.X12.Data837;
	set buildStat = $$$OK

	set elObjSub = $$$NULLOREF // 22, 2000B
	if ($GET(^ItfGlobalX12IdKey("X12Data" _ transType)) = "")
	 {
		$$$TRACE( "Create global: X12Data" _ transType)
	 	set ^ItfGlobalX12IdKey("X12Data" _ transType) = 1
	 }
	 else
	 {
		 Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
		 set elObj.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
	 }	  
	Do ..InitFirstObject(elObj, x12Doc, fileName, stat, receiptDtTm, direction, sessionId ) 
	set elObj.TtTransactionID = $ZSTRIP($ZDATETIME($HOROLOG,8, 2), "*P") _"-"_ sessionId

	set parentId = "", objCnt =0
	set GSCounter = x12Doc.ChildCount
	for gsInt=1:1:GSCounter
    { 
        #dim individualGroup As EnsLib.EDI.X12.Document
        set individualGroup = x12Doc.getNthChild(gsInt,2)

		$$$TRACE( "SessionId: " _ sessionId _ "GS: " _ gsInt _", # of STs: " _ individualGroup.ChildCount)


		  //set parentId = ""
		  FOR stInd=1:1:individualGroup.ChildCount
		  {
			  #dim STRecord As EnsLib.EDI.X12.Document 

			  set STRecord=individualGroup.getNthChild(stInd,2)		  

			  set STRecord.DocType = "HIPAA_5010:" _ transType
			  set buildStat = STRecord.BuildMap()

			  if ($$$ISERR(buildStat))
			  {
				  $$$LOGERROR("ST build: " _  transType_ ": " _  buildStat)
				  set elObj.Status = "Data"
				  Do elObj.%Save()

				  set parentId = elObj.%Id()
				  $$$TRACE( "  IHC.X12.Data837 ID: " _ elObj.%Id())

				  set elObjSub = elObj.%ConstructClone()				
				  Do elObjSub.x12DataStream.Clear()
			  }


			  $$$TRACE( "ST: " _  transType_ ", Seg Count: " _ STRecord.SegCountGet() )
			  set segX12Data = "", subCnt = 0

	  		  set entityType = ""
	  		  set newClm = 0, newSub = 0
			  FOR ind=1:1:STRecord.SegCountGet()
			  {

				set segPath = STRecord.GetSegmentPath(ind, .stat)	  	
			  	set segVal = STRecord.GetValueAt(segPath,, .stat)
			  	// $$$TRACE( segPath _" " _ segVal)

			  	if ($FIND(segVal,"CLM") = 4)
			  	{

				  	if (newClm = 1)
				  	{
					  	if ($IsObject(elObjSub))
					  	{
						  	Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
						  	set elObjSub.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
						  	set elObjSub.X12DataParentId = parentId
						  	set elObjSub.x12Data = segX12Data
						  	set elObjSub.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)
						  	if (elObjSub.Patient = "")
						  	{
							  	set elObjSub.Patient = elObjSub.Subscriber							  	
							  	set elObjSub.PatientGender = elObjSub.SubscriberGender
							  	set elObjSub.PatientDOB = elObjSub.SubscriberDOB
						  	}
						  	if (elObjSub.RenderingProvider = "")
						  	{
							  	set elObjSub.RenderingProvider = elObjSub.BillingProvider
							  	set elObjSub.RenderingProviderNpi = elObjSub.BillingProviderNpi
							  	set elObjSub.RenderingProviderTaxId = elObjSub.BillingProviderTaxId
						  	}


					  		Do $INCREMENT(objCnt)
					  		set elObjSub.SeqNum = objCnt
					  		Do elObjSub.%Save()
					  		$$$TRACE( "CLM IHC.X12.Data837 ID: " _ elObjSub.%Id())
					  		set elObjSub = elObj.%ConstructClone()
					  		Do elObjSub.x12DataStream.Clear()			  		
					  	}
				  	}

				  	set elObjSub.ClaimId = $PIECE(segVal, x12Doc.ElementSeparator , 2)
				  	set elObjSub.ClaimAmount = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  	if (' elObjSub.ClaimAmount [ ".")
				  	{
					  	set elObjSub.ClaimAmount = elObjSub.ClaimAmount _".00"
				  	}


					set segX12Data = segVal _ STRecord.SegmentTerminator // Start new X12 segment


					set elObjSub.SeqNum = objCnt
					set newClm = 1

			  	}
			  	elseif ($FIND(segVal,"BHT") = 4)
			  	{
				  	set elObj.BhtId = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	set seg1Val = $PIECE(segVal, x12Doc.ElementSeparator , 7)
				  	if (seg1Val '= "")
				  	{
				  		Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.Bht6Lookup", seg1Val, .retVal)

				  		set elObj.BhtPurpose = retVal 

				  		$$$TRACE(  segVal _" - " _ retVal)
				  	}
			  	}
			  	elseif (($FIND(segVal,"REF") = 4))
			  	{
				  	if ($PIECE(segVal, x12Doc.ElementSeparator , 2) = "D9")
				  	{
					  	if ($IsObject(elObjSub))
					  	{
					  		set elObjSub.ClearinghouseTraceNumber = $PIECE(segVal, x12Doc.ElementSeparator , 3) 
					  	}
						set elObj.ClearinghouseTraceNumber = $PIECE(segVal, x12Doc.ElementSeparator , 3) 

				  	}
				  	elseif ($PIECE(segVal, x12Doc.ElementSeparator , 2) = "EI")
				  	{					  	
				  		if ($IsObject(elObjSub))
				  		{				  	
					  		set elObjSub.BillingProviderTaxId = $PIECE(segVal, x12Doc.ElementSeparator , 3) 
					  	}

					  	set elObj.BillingProviderTaxId = $PIECE(segVal, x12Doc.ElementSeparator , 3) 
				  	}
			  	}
			  	elseif ($FIND(segVal,"DTP") = 4)
			  	{
				  	set seg1Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
				  	Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.DTPLookup", seg1Val, .retVal)

				  	if (seg1Val = "472") 
				  	{
				  		set elObjSub.ServiceDate = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
				  	if (seg1Val = "434") 
				  	{
				  		set elObjSub.ServiceDate = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
			  	}


			  	elseif ($FIND(segVal,"DMG") = 4)
			  	{
				  	if (entityType = "Subscriber")
				  	{
				  	set elObjSub.SubscriberDOB = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  	set elObjSub.SubscriberGender = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
				  	elseif (entityType = "Patient")
				  	{
				  	set elObjSub.PatientDOB = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  	set elObjSub.PatientGender = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
			  	}
			  	elseif ($FIND(segVal,"NM1") = 4)
			  	{

				  	set seg1Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
				  	Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.NM1lookup", seg1Val, .retVal)

				  	if (seg1Val = "40")
				  	{
					  	set elObj.Receiver = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
				  	if (seg1Val = "41")
				  	{
					  	set elObj.Submitter = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
				  	if (seg1Val = "85")
				  	{
					  	set elObj.BillingProvider = $PIECE(segVal, x12Doc.ElementSeparator , 5) _ " " _ $PIECE(segVal, x12Doc.ElementSeparator , 4)
					  	set elObj.BillingProviderNpi = $PIECE(segVal, x12Doc.ElementSeparator , 10) 
				  	}

				  	if (seg1Val = "PR")
				  	{
					  	set elObjSub.Payer = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
				  	if (seg1Val = "IL")
				  	{
					  	set elObjSub.Subscriber = $PIECE(segVal, x12Doc.ElementSeparator , 5) _ " " _ $PIECE(segVal, x12Doc.ElementSeparator , 4)
					  	set elObjSub.SubscriberId = $PIECE(segVal, x12Doc.ElementSeparator , 10)
					  	set entityType = "Subscriber"
				  	}
				  	if (seg1Val = "QC")
				  	{
					  	set elObjSub.Patient = $PIECE(segVal, x12Doc.ElementSeparator , 5) _ " " _ $PIECE(segVal, x12Doc.ElementSeparator , 4)
					  	set entityType = "Patient"
				  	}
				  	if ( (seg1Val = "82") || (seg1Val = "71")) // Rendering or Attending
				  	{

					  	set elObjSub.RenderingProvider = $PIECE(segVal, x12Doc.ElementSeparator , 5) _ " " _ $PIECE(segVal, x12Doc.ElementSeparator , 4)
					  	set elObjSub.RenderingProviderNpi = $PIECE(segVal, x12Doc.ElementSeparator , 10)
				  	}

			  	}
			  	elseif ($FIND(segVal,"HI") = 3)
			  	{
				  	if ($PIECE(segVal, x12Doc.ElementSeparator , 2) [ "ABK")
				  	{
					 	set elObjSub.DiagnosisCode = $PIECE(segVal, x12Doc.ElementSeparator , 2)
				  	}

			  	}


			  	elseif ($FIND(segVal,"ST") = 3)
			  	{
				  	set elObj.TransactionSetControlNumber = $PIECE(segVal, x12Doc.ElementSeparator , 3)
			  	}
			  	elseif ($FIND(segVal,"SE") = 3) 
			  	{

					Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
					set elObjSub.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
					set elObjSub.X12DataParentId = parentId
					set elObjSub.x12Data = segX12Data
					set elObjSub.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)  
					if (elObjSub.Patient = "")
				  	{
					  	set elObjSub.Patient = elObjSub.Subscriber
					  	set elObjSub.PatientGender = elObjSub.SubscriberGender
					  	set elObjSub.PatientDOB = elObjSub.SubscriberDOB
				  	}
				  	if (elObjSub.RenderingProvider = "")
				  	{
					  	set elObjSub.RenderingProvider = elObjSub.BillingProvider
					  	set elObjSub.RenderingProviderNpi = elObjSub.BillingProviderNpi
					  	set elObjSub.RenderingProviderTaxId = elObjSub.BillingProviderTaxId
				  	}

				  	Do $INCREMENT(objCnt)
				  	set elObj.SeqNum = objCnt	  		
				  	set stat = elObjSub.%Save()
				  	set newSub = 0, newClm = 0
				  	$$$TRACE( "-- SE Save -- " _ stat _", Id: " _ elObjSub.%Id() _", Parent: " _ parentId)
				  	set elObjSub = elObj.%ConstructClone()
				  	Do elObjSub.x12DataStream.Clear()
			  	}

			  	elseif ($FIND(segVal,"HL") = 3)
			  	{
				  	$$$TRACE( " -- HL -- " _ segVal _", Id: " _ elObj.%Id() _", HL-1: " _ $PIECE(segVal, x12Doc.ElementSeparator , 2) )
	  			  	set seg3Val = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.HlCodeLookup", seg3Val, .retVal)
				  	if (seg3Val = 22)
				  	{

					  	if (newSub = 1)
					  	{
						  	Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
						  	set elObjSub.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
						  	set elObjSub.X12DataParentId = parentId
						  	set elObjSub.x12Data = segX12Data
						  	set elObjSub.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)
						  	if (elObjSub.Patient = "")
						  	{
							  	set elObjSub.Patient = elObjSub.Subscriber
							  	set elObjSub.PatientGender = elObjSub.SubscriberGender
							  	set elObjSub.PatientDOB = elObjSub.SubscriberDOB
						  	}
						  	if (elObjSub.RenderingProvider = "")
						  	{
							  	set elObjSub.RenderingProvider = elObjSub.BillingProvider
							  	set elObjSub.RenderingProviderNpi = elObjSub.BillingProviderNpi
							  	set elObjSub.RenderingProviderTaxId = elObjSub.BillingProviderTaxId
						  	}
					  		Do elObjSub.%Save()
					  		Do $INCREMENT(objCnt)
					  		$$$TRACE( "HL IHC.X12.Data837 ID: " _ elObjSub.%Id())
					  		set elObjSub = elObj.%ConstructClone()
					  		Do elObjSub.x12DataStream.Clear()
					  	}
					  	set elObjSub = elObj.%ConstructClone()
					  	Do elObjSub.x12DataStream.Clear()
					  	set newSub = 1, newClm = 0
					  	set elObjSub.SeqNum = $PIECE(segVal, x12Doc.ElementSeparator , 2)

				  	}

				  	elseif ( (elObj.%Id() = "") &&($PIECE(segVal, x12Doc.ElementSeparator , 2) = 1) ) // First HL, parent
				  	{

				  		  set stat = elObj.%Save()
				  		  if $$$ISERR(stat)
				  		  {
				  		  	$$$TRACE( "Claim save: " _ stat)
				  		  	DO $System.Status.DisplayError(stat)
				  		  	return $$$OK
				  		  }
				  		  Do $INCREMENT(objCnt)
						  set parentId = elObj.%Id()
						  $$$TRACE( " Parent IHC.X12.Data837 ID: " _ elObj.%Id() _ ", X12 Data: " _ $L(elObj.x12Data) _ ", Stream: " _ elObj.x12DataStream.Size)					   				  


						  set elObjSub = $$$NULLOREF
						  set elObjSub = elObj.%ConstructClone()
						  Do elObjSub.x12DataStream.Clear()
						  set newSub = 0, newClm = 0
						  set elObjSub.SeqNum = $PIECE(segVal, x12Doc.ElementSeparator , 2)
			  		}
			  	}

			  	else
			  	{
				  	// WRITE !, "      ***** Not stored: " _ segVal
			  	}
			  	if ($FIND(segVal,"CLM") '= 4)
			  	{
			  		set segX12Data = segX12Data _ segVal _ STRecord.SegmentTerminator // Append data
			  	}
			  }
		  }
		  set elObj.SeqNum = objCnt - 1
		  Do elObj.%Save()

     }
     if ( (objCnt = 0) && ($$$ISERR(buildStat)) )
     {
     	// Add an entry to WorkFlow
		Do ..InsertWF(elObj, transType)
     }


	 $$$TRACE( " --- Processing complete: IHC.X12.Data837, Claim, # rows:" _ objCnt)
	 return elObj.%Id()

	set elObj = ##class(IHC.X12.Data270).%New()
	Do ..InitFirstObject(elObj, x12Doc, fileName, stat, receiptDtTm, direction, sessionId ) 
	if ($GET(^ItfGlobalX12IdKey("X12Data" _ transType)) = "")
	 {
		$$$TRACE( "Create global: X12Data" _ transType)
	 	set ^ItfGlobalX12IdKey("X12Data" _ transType) = 1
	 }
	 else
	 {
		 Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
		 set elObj.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
	 }

	set parentId = "", objCnt =0
	set GSCounter = x12Doc.ChildCount
	for gsInt=1:1:GSCounter
    { 
        #dim individualGroup As EnsLib.EDI.X12.Document
        set individualGroup = x12Doc.getNthChild(gsInt,2)


		  $$$TRACE( "Process270 # of STs: " _ individualGroup.ChildCount)
		  set parentId = "", objCnt =0, elClmObj = $$$NULLOREF // 2100
		  FOR stInd=1:1:individualGroup.ChildCount
		  {

			  #dim STRecord As EnsLib.EDI.X12.Document 

			  set STRecord=individualGroup.getNthChild(stInd,2)

			  set STRecord.DocType = "HIPAA_5010:" _ transType
			  set stat = STRecord.BuildMap()

			  if ($$$ISERR(stat))
			  {
				  $$$LOGERROR("ST build: " _  transType_ ": " _  stat)
				  set elObj.Status = "Data"
				  Do elObj.%Save()

				  set parentId = elObj.%Id()
				  $$$TRACE( "  IHC.X12.Data270 ID: " _ elObj.%Id())
				  //return ""

			  }


			  $$$TRACE(  "ST: " _  transType_ ", Seg Count: " _ STRecord.SegCountGet() )
			  set segX12Data = "", subCnt = 0

	  		  set elObjSub = $$$NULLOREF, hlVal = ""
			  FOR ind=1:1:STRecord.SegCountGet()
			  {

				set segPath = STRecord.GetSegmentPath(ind, .stat)	  	
			  	set segVal = STRecord.GetValueAt(segPath,, .stat)


			  	if ($FIND(segVal,"TRN") = 4)
			  	{

				  	set elObjSub.TrnRefId = $PIECE(segVal, x12Doc.ElementSeparator , 3)
			  	}
			  	elseif ($FIND(segVal,"BHT") = 4)
			  	{
				  	set elObj.BhtId = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	set seg1Val = $PIECE(segVal, x12Doc.ElementSeparator , 7)
				  	if (seg1Val '= "")
				  	{
				  		Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.Bht6Lookup", seg1Val, .retVal)

				  		set elObj.BhtPurpose = retVal 

				  		$$$TRACE(  segVal _" - " _ retVal)
				  	}
			  	}
			  	elseif ($FIND(segVal,"DTP") = 4)
			  	{
				  	set seg1Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
				  	Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.DTPLookup", seg1Val, .retVal)

				  	if (seg1Val = "291") // 291: (Plan,Range of dates for which the plan is in effect)
				  	{
				  		set elObjSub.PlanDate = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
			  	}

			  	elseif ($FIND(segVal,"DMG") = 4)
			  	{
				  	if (hlVal = "Subscriber")
				  	{
				  	set elObjSub.SubscriberDOB = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  	set elObjSub.SubscriberGender = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
				  	elseif (hlVal = "Dependent")
				  	{
				  	set elObjSub.DependentDOB = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  	set elObjSub.DependentGender = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
			  	}
			  	elseif ($FIND(segVal,"NM1") = 4)
			  	{

				  	set seg1Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
				  	Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.NM1lookup", seg1Val, .retVal)


				  	if (seg1Val = "PR")
				  	{
					  	set elObj.Payer = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
				  	if ((seg1Val = "1P") || (seg1Val = "FA"))
				  	{
					  	set elObj.Provider = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
				  	if (seg1Val = "IL")
				  	{
					  	set elObjSub.Subscriber = $PIECE(segVal, x12Doc.ElementSeparator , 5) _ " " _ $PIECE(segVal, x12Doc.ElementSeparator , 4)
					  	set elObjSub.SubscriberId = $PIECE(segVal, x12Doc.ElementSeparator , 10)
				  	}
				  	if (seg1Val = "03")
				  	{
					  	set elObjSub.Dependent = $PIECE(segVal, x12Doc.ElementSeparator , 5) _ " " _ $PIECE(segVal, x12Doc.ElementSeparator , 4)
					  	set elObjSub.DependentId = $PIECE(segVal, x12Doc.ElementSeparator , 10)
				  	}
			  	}
			  	elseif ($FIND(segVal,"HL") = 3)
			  	{
	  			  	set seg3Val = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.HlCodeLookup", seg3Val, .retVal)
				  	if ($IsObject(elObjSub))
				  	{
					  	Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
					  	set elObjSub.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
					  	set elObjSub.X12DataParentId = parentId
					  	set elObjSub.x12Data = segX12Data
					  	set elObjSub.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)
				  		set stat = elObjSub.%Save()
				  		Do $INCREMENT(objCnt)
				  		$$$TRACE(  "IHC.X12.Data270 ID: " _ elObjSub.%Id() _", Status: " _ stat)

				  	}
				  	elseif( (elObj.Payer '= "") && (elObj.Provider '= ""))
				  	{
				  		  Do elObj.%Save()
				  		  Do $INCREMENT(objCnt)
						  set parentId = elObj.%Id()					   				  
						  set elObjSub = elObj.%ConstructClone()
						  set elObjSub.x12Data = ""
						  Do elObjSub.x12DataStream.Clear()
						  set elObjSub.SeqNum = $PIECE(segVal, x12Doc.ElementSeparator , 2)
			  		}



				  	set hlVal = retVal // HL level code

				  	if (hlVal = "Subscriber")
				  	{
					  	set elObjSub = elObj.%ConstructClone()
					  	Do elObjSub.x12DataStream.Clear()
					  	set segX12Data = segVal _ STRecord.SegmentTerminator // Start new X12 segment
					  	set elObjSub.SeqNum = $PIECE(segVal, x12Doc.ElementSeparator , 2)
					  	Do $INCREMENT(subCnt)
				  	}
				  	else
				  	{
					  	set segX12Data = segX12Data _ segVal _ STRecord.SegmentTerminator // Append Dependent HL data
				  	}
			  	} //HL

			  	elseif ($FIND(segVal,"ST") = 3)
			  	{
				  	set elObj.TransactionSetControlNumber = $PIECE(segVal, x12Doc.ElementSeparator , 3)
			  	}
			  	elseif ($FIND(segVal,"SE") = 3) 
			  	{

					Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
					set elObjSub.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
					set elObjSub.X12DataParentId = parentId
					set elObjSub.x12Data = segX12Data
					set elObjSub.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)  	
				  	set stat = elObjSub.%Save()
				  	Do $INCREMENT(objCnt)
				  	$$$TRACE(  "IHC.X12.Data270 ID: " _ elObjSub.%Id() _", Status: " _ stat)
			  	}

			  	else
			  	{
				  	// WRITE !, "      ***** Not stored: " _ segVal
			  	}
			  	if ($FIND(segVal,"HL") '= 3)
			  	{
			  		set segX12Data = segX12Data _ segVal _ STRecord.SegmentTerminator // Append data
			  	}
			  }
		  }
		  set elObj.SeqNum = objCnt - 1

		  set stat = elObj.%Save()
		  $$$TRACE(  "IHC.X12.Data270 ID: " _ elObj.%Id() _", Status: " _ stat)
    }
	$$$TRACE( " --- Processing complete: IHC.X12.Data270, EligibilityRequest, # rows:" _ objCnt)
	return elObj.%Id()

	set elObj = ##class(IHC.X12.Data271).%New()
	Do ..InitFirstObject(elObj, x12Doc, fileName, stat, receiptDtTm, direction, sessionId ) 
	set parentId = "", objCnt =0
	set GSCounter = x12Doc.ChildCount

	if ($GET(^ItfGlobalX12IdKey("X12Data" _ transType)) = "")
	 {
		$$$TRACE(  "Create global: X12Data" _ transType)
