	 }
	set ta1Obj.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
	if ( ($ISOBJECT(x12Doc)) && (x12Doc.%Extends("EnsLib.EDI.X12.Document")) )
    {
		 if (x12Doc.DocType = "")
		 {

