				Set tSC =x12Doc.BuildMap()
		 }


	    set InterchangeReceiverID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeReceiverID"), "<>W")
	    set InterchangeSenderID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeSenderID"), "<>W")
	    set InterchangeCtrlNum = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeControlNumber"),"<","0")

	   $$$TRACE(  "TA1: " _ InterchangeSenderID _" -> " _ InterchangeReceiverID _", Ctrl #" _InterchangeCtrlNum) 

	   set x12Doc.DocType = "HIPAA_5010:Interchange:Group" 

       set mmId = $EXTRACT($ZDATE($HOROLOG, 8), 1, 6)


	   for seg=1:1:x12Doc.SegCount
	   {
		if (x12Doc.GetSegmentAt(seg).Name = "TA1")
		{
			set ta1Obj.FileName = ##class(%File).GetFilename(fileName)
			  set ta1Obj.MonthPartition = mmId

			  set ta1Obj.InterchangeControlNumber = InterchangeCtrlNum
			  set ta1Obj.InterchangeDateTime = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeDate"), "<>W") _ $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeTime"), "<>W")
			  set ta1Obj.InterchangeReceiverID = InterchangeReceiverID
			  set ta1Obj.InterchangeReceiverName = ..GetTpName(InterchangeReceiverID)
			  set ta1Obj.InterchangeSenderID = InterchangeSenderID

		 	set ta1Obj.ControlNumber = x12Doc.GetSegmentAt(seg).GetValueAt(1) 
		 	set ta1Obj.AcknowledgeCode = x12Doc.GetSegmentAt(seg).GetValueAt(4) 
		 	set ta1Obj.NoteCode = x12Doc.GetSegmentAt(seg).GetValueAt(5)
		 	set ta1Obj.Status = "Processed"

		 	set ta1Obj.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)
			  set ta1Obj.ReceiptDtTm = receiptDtTm
			  set ta1Obj.SessionID = sessionId



			      set ta1Obj.x12Data = x12Doc.OutputToString(,.stat,)
			      if (stat '= 1)
			      {
				      $$$TRACE(  " --- The length of the document is greater than the maximum string length ---")
			      }


		 	set stat = ta1Obj.%Save()
		 	$$$TRACE("TA1 ID: " _ ta1Obj.%Id() _ ", stat:" _ stat)

		 }
	   }
    }
	return ta1Obj.%Id()

set transType = ""
if ( $IsObject(STRecord))
{
	set transType = STRecord.GetValueAt("1:1",, .stat)


  if (STRecord.GetValueAt("1",, .stat) [ "005010X222A1")
	{
		set transType = transType _"P"
	}
	elseif (STRecord.GetValueAt("1",, .stat) [ "005010X223A2")
	{
		set transType = transType _"I"
	}
	elseif (STRecord.GetValueAt("1",, .stat) [ "005010X224A2")
	{
		set transType = transType _"D"
	}
	elseif (STRecord.GetValueAt("1",, .stat) [ "005010X214")
	{
		set transType = transType _"CA"
	}
}
return transType

	  set InterchangeCtrlNum = x12Doc.GetValueAt("ISA:InterchangeControlNumber")
