	  set elObj.InterchangeReceiverID = InterchangeReceiverID
	  set elObj.InterchangeReceiverName = ..GetTpName(InterchangeReceiverID)
	  set elObj.InterchangeSenderID = InterchangeSenderID
	  set elObj.InterchangeSenderName = ..GetTpName(InterchangeSenderID)
	  if ( $zconvert(direction, "u")  [ "IN")
	  {
	  	  set elObj.Direction = "Inbound"
	  }
	  else
	  {
		  set elObj.Direction = "Outbound"
	  }
	  set elObj.SessionID = sessionId
	  if (x12Doc.ChildCount > 0)
	  {

		  #dim individualGroup As EnsLib.EDI.X12.Document 
		  set individualGroup = x12Doc.getNthChild(1,2)

		  set isaGsInfo =  InterchangeSenderID _" -> " _ InterchangeReceiverID _ ", ControlNumbers: " _ InterchangeCtrlNum _", " _ individualGroup.GetValueAt("GS:GroupControlNumber")
	      $$$TRACE( isaGsInfo _ ", # of STs: " _ individualGroup.ChildCount) 

		  set elObj.GroupControlNumber = individualGroup.GetValueAt("GS:GroupControlNumber")
		  set elObj.ApplicationReceiversCode = individualGroup.GetValueAt("GS:ApplicationReceiversCode")
		  set elObj.ApplicationSendersCode = individualGroup.GetValueAt("GS:ApplicationSendersCode")
		  set elObj.VersionReleaseIndustryIdenti =  individualGroup.GetValueAt("GS:VersionReleaseIndustryIdenti")
	  }
	  set elObj.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)
	  set elObj.ReceiptDtTm = receiptDtTm
	  set elObj.Status = stat


	  if (##class(%File).GetFileSize(fileName)  > 3641143) // Property x12Data As %String(MAXLEN = 3641144);
	  {

		  Set elObj.x12DataStream=##class(%FileCharacterStream).%New()
		  set stat = x12Doc.OutputToLibraryStream(elObj.x12DataStream)
		  $$$TRACE( " --- OutputToLibraryStream: " _ stat _", The X12 data is stored as x12DataStream, size: " _  elObj.x12DataStream.Size)
	  }
	  else
	  {
	      set elObj.x12Data = x12Doc.OutputToString(,.stat,)
	      if (stat '= 1)
	      {
		      $$$TRACE( " --- The length of the document is greater than the maximum string length ---")
		      Set elObj.x12DataStream=##class(%FileCharacterStream).%New()
  		      set stat = x12Doc.OutputToLibraryStream(elObj.x12DataStream)
  		      set elObj.x12Data = ""
  		      $$$TRACE( " --- OutputToLibraryStream: " _ stat _", The X12 data is stored as x12DataStream, size: " _  elObj.x12DataStream.Size)

	      }
	      else
	      {
		      $$$TRACE( "Inbound X12 length: " _ $L(elObj.x12Data))
	      }
	  }

	   /// Create 999 by calling X12BatchReply, Update 3 fields from 999 
	   	  #dim rep As EnsLib.EDI.X12.Document = ##class(Ens.X12.FunctionSet).X12BatchReply(x12Doc,, "SNIP", 1)
	   	  if ( ($ISOBJECT(rep)) && (rep.%Extends("EnsLib.EDI.X12.Document")) )
  		  {	  
  		  	  set repStr = rep.OutputToString()
  		  	  set elObj.TransactionsReceived = 0, elObj.TransactionsAccepted = 0
  		  	  if ($L(repStr) > 1)
  		  	  {
	  		  	  $$$TRACE( "X12BatchReply: " _ repStr)
	  		  	  set repGSCounter = rep.ChildCount
                  set segX12Data = "", repGSnum = 1
		          while ( repGSnum <= repGSCounter)
		          { 
		            set repGrp = rep.getNthChild(repGSnum,2)
		            if $ISOBJECT(repGrp)
		            {
			            set repGrp.DocType = "HIPAA_5010:Group"


				        set repSTCounter = repGrp.ChildCount 

				        #dim repST As EnsLib.EDI.X12.Document
				        set repSTnum = 1
				        while ( repSTnum <= repSTCounter)
				        { 
				          set repST = repGrp.getNthChild(repSTnum)
				          $$$TRACE( "999 from Ens.X12.FunctionSet: " _ repST.RawContent)

				          set GroupRespAckCode = repST.GetValueAt("AK9")
						  set elObj.TransactionsStatus = $PIECE(GroupRespAckCode, rep.ElementSeparator , 2)

						  set elObj.TransactionsReceived = elObj.TransactionsReceived + $NUMBER($PIECE(GroupRespAckCode, rep.ElementSeparator, 3),"I")
						  if (elObj.TransactionsStatus = "A")
						  {
						  	set elObj.TransactionsAccepted = elObj.TransactionsAccepted + $NUMBER($PIECE(GroupRespAckCode, rep.ElementSeparator, 4), "I")
						  }


				          Do $INCREMENT(repSTnum)
				        }
		            }
		            else
		            {
			            // TA1
			            set elObj.TransactionsReceived = 1, elObj.TransactionsAccepted = 0
		            }
			        Do $INCREMENT(repGSnum) 


          		  } 


				  $$$TRACE( "Transactions values from AK9: " _ elObj.TransactionsStatus _", Received: " _ elObj.TransactionsReceived _", TransactionsAccepted: " _ elObj.TransactionsAccepted)

  		  	  }
  		  	  else
  		  	  {
	  		  	  $$$TRACE( "Invalid X12BatchReply")
  		  	  }

  		  	  if ($IsObject(rep))
			  {
			    Do rep.%Save()
			  	set repId = rep.%Id()
			  	set delStat = rep.%DeleteId(rep.%Id())
			  	$$$TRACE( "ProcessX12Doc Delete 999: " _ delStat _", ID: " _ repId)
			  }



  		  }
  		  else
  		  {
	  		  $$$TRACE( "X12BatchReply failed ") 
  		  }
